CREATE OR REPLACE FUNCTION handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE next_id integer; new_slug_id text; existing_ghost uuid; BEGIN SELECT id INTO existing_ghost FROM profiles WHERE email = new.email AND is_claimed = false; IF existing_ghost IS NOT NULL THEN UPDATE profiles SET id = new.id, is_claimed = true WHERE id = existing_ghost; RETURN new; END IF; SELECT COALESCE(MAX(CAST(SUBSTRING(slug_id FROM 8) AS integer)), 0) + 1 INTO next_id FROM profiles WHERE slug_id LIKE 'BH-' || to_char(now(), 'YY') || '-%'; new_slug_id := 'BH-' || to_char(now(), 'YY') || '-' || lpad(next_id::text, 3, '0'); INSERT INTO profiles (id, email, slug_id, role, is_claimed) VALUES (new.id, new.email, new_slug_id, 'hacker', true); RETURN new; END; $$; CREATE OR REPLACE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE PROCEDURE handle_new_user();
